System.Func<string, System.Collections.Generic.Dictionary<(string, int, int), string>> parse = s =>
{
    var d = new System.Collections.Generic.Dictionary<(string, int, int), string>();
    foreach (var line in s.Split('\n'))
    {
        if (line.Trim().Length == 0) continue;
        var p = line.Split(' ');
        d[(p[0], int.Parse(p[1]), int.Parse(p[2]))] = p[3];
    }
    return d;
};
