{
    if (g.name == "Rooms") rooms = g;
    if (g.name == "Grid")
        foreach (var tm in g.GetComponentsInChildren<UnityEngine.Tilemaps.Tilemap>(true))
        {
            if (tm.name == "Ground Tilemap") ground = tm;
            if (tm.name == "Wall Tilemap") wall = tm;
        }
}
if (rooms == null || ground == null || wall == null) return "중단: Rooms · Ground · Wall 타일맵을 못 찾음";
var others = new System.Collections.Generic.List<UnityEngine.Tilemaps.Tilemap>();
foreach (UnityEngine.Transform r in rooms.transform)
    if (r.name != "Halls_Decor")
        foreach (var tm in r.GetComponentsInChildren<UnityEngine.Tilemaps.Tilemap>(true))
            if (!tm.name.EndsWith(" Decal") && !tm.name.EndsWith(" Water") && !tm.name.EndsWith(" Pond Frame") && !tm.name.EndsWith(" Plate")) others.Add(tm);
int bad = 0;
foreach (var kv in want)
{
    var (map, x, y) = kv.Key;
    var cell = new UnityEngine.Vector3Int(x, y, 0);
    string why = null;
    if (map == "Decor" && !wall.HasTile(cell)) why = "벽걸이 칸에 벽 없음";
    if (map == "Block" && (!ground.HasTile(cell) || wall.HasTile(cell))) why = "바닥 광원 칸이 바닥이 아님";
    foreach (var tm in others)
    {
        // 다른 방 프리팹 타일 (인스턴스 위치 반영)
        var local = tm.WorldToCell(ground.GetCellCenterWorld(cell));
        if (tm.HasTile(local)) { why = "겹침 " + tm.name; break; }
    }
    if (why != null) { bad++; if (bad <= 30) sb.AppendLine($"  {map} {x},{y} {System.IO.Path.GetFileNameWithoutExtension(kv.Value)}: {why}"); }
}
