    var inst = (UnityEngine.GameObject)UnityEditor.PrefabUtility.InstantiatePrefab(basePrefab, scene);
    inst.name = "Halls_Decor";
    foreach (UnityEngine.Transform t in inst.transform) t.name = "Halls " + t.name;
    var emitter = inst.AddComponent<ShotgunAndRun.Environment.TileLightEmitter>();
    var so = new UnityEditor.SerializedObject(emitter);
    so.FindProperty("_table").objectReferenceValue = UnityEditor.AssetDatabase.LoadAssetAtPath<ShotgunAndRun.Environment.LightSourceTable>(TablePath);
    so.ApplyModifiedPropertiesWithoutUndo();
    inst.transform.SetParent(rooms.transform, false);
    inst.transform.localPosition = UnityEngine.Vector3.zero;
    inst.transform.SetAsLastSibling();
    UnityEditor.PrefabUtility.SaveAsPrefabAssetAndConnect(inst, PrefabPath, UnityEditor.InteractionMode.AutomatedAction);
    UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);
    UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);
    sb.AppendLine("프리팹 만듦 · 씬 저장");
}

// 칠하기 (프리팹 파일)
var root = UnityEditor.PrefabUtility.LoadPrefabContents(PrefabPath);
var maps = new System.Collections.Generic.Dictionary<string, UnityEngine.Tilemaps.Tilemap>();
foreach (var tm in root.GetComponentsInChildren<UnityEngine.Tilemaps.Tilemap>(true)) maps[tm.name.Replace("Halls ", "")] = tm;
var cache = new System.Collections.Generic.Dictionary<string, UnityEngine.Tilemaps.TileBase>();
System.Func<string, UnityEngine.Tilemaps.TileBase> load = p =>
{
    if (!cache.TryGetValue(p, out var t)) cache[p] = t = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Tilemaps.TileBase>(p);
    return t;
};
