int handEdits = 0, total = 0;
foreach (var kv in maps)
{
    var tm = kv.Value;
    tm.CompressBounds();
    foreach (var c in tm.cellBounds.allPositionsWithin)
    {
        var t = tm.GetTile(c);
        if (t == null) continue;
        total++;
        var key = (kv.Key, c.x, c.y);
        if (!prev.TryGetValue(key, out var p) || UnityEditor.AssetDatabase.GetAssetPath(t) != p) handEdits++;
    }
}
if (handEdits > 0 || total != prev.Count)
