        foreach (var tm in r.GetComponentsInChildren<UnityEngine.Tilemaps.Tilemap>(true)) { tm.CompressBounds(); foreach (var c in tm.cellBounds.allPositionsWithin) if (tm.HasTile(c)) n++; }
        sb.AppendLine($"씬 인스턴스: 타일 {n}, 빛 {e.SourceCount}, 오버라이드 {UnityEditor.PrefabUtility.GetObjectOverrides(r.gameObject).Count}, 씬 dirty {scene.isDirty}");
